/* Independent visual exploration. Facts are copied from the current demo baseline. */
window.REVIEW_VIEWS=(()=>{
  const D=window.REVIEW_DATA;
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon=(name,cls='')=>`<svg class="ico ${cls}" viewBox="0 0 24 24" aria-hidden="true">${D.icons[name]||D.icons.circle}</svg>`;
  const btn=(label,action,name='',cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${name?icon(name):''}${label}</button>`;
  const link=(label,action,name='arrow-up-right',attrs='')=>`<button type="button" class="link-btn" data-action="${action}" ${attrs}>${label}${name?icon(name):''}</button>`;
  const tag=(text,tone='',name='')=>`<span class="tag ${tone}">${name?icon(name):''}${text}</span>`;
  const fmt=(n,d=2)=>Number(n).toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d});
  const money=n=>fmt(n/100)+'<small>亿元</small>';
  const company=id=>D.enterprises.find(e=>e.id===id)||D.enterprises.find(e=>e.id==='ENT-020');
  const riskCompanies=D.enterprises.filter(e=>e.riskTier!=='绿灯').sort((a,b)=>a.riskScore-b.riskScore);
  const pages={query:['问数工作台','message-square','ASK & UNDERSTAND','让每个业务问题，都有可追溯的回答。','01'],map:['地图视图','map','EXPLORE YOUR BUSINESS','从企业位置到业务关系，在同一视图中理解全局。','02'],decision:['决策中心','git-pull-request-arrow','REVIEW & ACT','带着依据进入研判，让每一步办理都有明确边界。','03'],ontology:['本体工作台','network','CONNECT THE MEANING','把数据、业务规则与行动，组织成可理解的语义。','04']};
  const phases=['待研判','待批准','待承接','执行中','效果待复核','已结项'];phases[-1]='已拒绝';
  const themes={a:{name:'明晰蓝白',subtitle:'操作与汇报兼顾',label:'A',colors:['#122a45','#f3f6fb','#2c66d3','#238776'],summary:'沿用企业工作台的稳定秩序，用明亮画布、较大字号和三栏分工，让结论、依据与下一步同时清楚。',fit:'日常工作 + 会议投屏',tradeoff:'信息最完整，视觉冲击更克制。'},b:{name:'深海指挥台',subtitle:'全局态势优先',label:'B',colors:['#091a27','#112736','#60d2c3','#e2b56e'],summary:'把主导航移到顶部，工作区横向展开。深海蓝背景与青绿数据建立明确焦点，地图和关键结论获得最大的展示面积。',fit:'专题演示 + 暗场会议',tradeoff:'亮场投影需确认对比度；长时间细表阅读偏好因人而异。'},c:{name:'暖白研判室',subtitle:'结论与证据并置',label:'C',colors:['#f5f2eb','#eeece3','#386652','#a07a42'],summary:'采用暖白纸感、墨绿行动和编辑式标题，以留白与细线组织信息。像阅读一份可操作的研判报告，强调解释与判断。',fit:'管理层评审 + 业务讲解',tradeoff:'单屏信息密度较低，细节更多通过抽屉展开。'}};
  function reviewBar(s){return `<div class="review-brand"><b>DESIGN REVIEW</b><div>智财问策 · 大屏选型<small>3 种风格 × 4 个关键页面 · 独立交互预览</small></div></div><nav class="variant-switch" aria-label="选择视觉方案">${Object.entries(themes).map(([key,t])=>`<button type="button" data-variant="${key}" class="${s.variant===key?'active':''}" aria-pressed="${s.variant===key}"><i class="swatch ${key}"></i><span><strong>${t.label} · ${t.name}</strong><small>${t.subtitle}</small></span></button>`).join('')}</nav><div class="review-actions"><button type="button" data-action="design-notes">方案说明</button><button type="button" data-action="preservation">功能保留</button><button type="button" data-action="presentation">进入演示</button></div>`;}
  function shell(s){const p=pages[s.page];return `<div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-symbol">${icon('network')}</span><div><strong>智财问策</strong><small>ONTOLOGY FINANCIAL WORLD</small></div></div><div class="nav-caption">WORKSPACE / 工作空间</div><nav class="side-nav" aria-label="应用导航">${Object.entries(pages).map(([key,val])=>`<button type="button" data-page="${key}" aria-label="${val[0]}" title="${val[0]}" class="${s.page===key?'active':''}" ${s.page===key?'aria-current="page"':''}><span class="nav-number">${val[4]}</span>${icon(val[1])}<span>${val[0]}</span>${key==='query'?'<small>AI</small>':''}</button>${key===s.page?`<div class="nav-sub">${({query:['当前会话','历史与保存视图'],map:['企业探索','地图 / 关系 / 时序'],decision:['事项工作台','运营总览'],ontology:['本体建模','版本与消费证据']})[key].map(x=>`<span>${x}</span>`).join('')}</div>`:''}`).join('')}</nav><div class="nav-secondary"><button data-action="modules">${icon('database')}数据工程</button><button data-action="models">${icon('workflow')}模型与算法</button><button data-action="modules">${icon('bot')}Agent 应用</button><button data-action="report">${icon('file-text')}报告中心</button></div><footer class="nav-bottom"><button data-action="modules">${icon('panel-left-close')}全部功能入口</button><span><i class="status-dot"></i>演示数据 · 2025.12.31</span></footer></aside><section class="workspace"><header class="topbar"><nav class="breadcrumb" aria-label="当前位置">${icon('house')}<span>集团工作空间</span>${icon('chevron-right')}<b>${p[0]}</b></nav><div class="topbar-actions"><span>业务视图 / v1.5</span><i class="vertical-rule"></i><button aria-label="搜索资源" data-action="search">${icon('search')}</button><button aria-label="最近工作" data-action="history">${icon('history')}</button><span class="avatar">财</span><span>集团财务管理</span></div></header><main class="content" data-screen-label="${themes[s.variant].label} · ${p[0]}"><header class="page-heading"><div><span class="hero-number">${p[4]}</span><div class="eyebrow">${p[2]}</div><h1>${s.page==='ontology'?'企业业务全景本体':p[0]}</h1><p>${p[3]}</p></div><div class="heading-actions">${headingActions(s)}</div></header>${context(s)}${({query:queryView,map:mapView,decision:decisionView,ontology:ontologyView})[s.page](s)}<footer class="footer-note"><span>来源清楚，判断有据，行动留痕。</span><span>${s.page==='map'?'城市为示意位置 · Natural Earth / DataV':'设计选型样例 · 业务事实沿用原型演示数据'}　${s.page==='ontology'?'语义发布 ≠ 正式数据切换':'数据截至 2025-12-31'}</span></footer></main></section></div>`;}
  function headingActions(s){return s.page==='query'?btn('历史会话','history','history')+btn('新建会话','new-chat','plus'):s.page==='map'?btn('保存探索','save','bookmark')+btn('时序分析','temporal','chart-no-axes-combined','primary'):s.page==='decision'?btn('运营总览','overview','chart-column')+btn('新建待研判事项','new-case','plus','primary'):btn('版本与正式使用','versions','git-branch')+btn(s.ontologyMode==='published'?'修订为工作草稿':s.validated?'发布语义版本':'校验工作草稿',s.ontologyMode==='published'?'revise':s.validated?'publish':'validate',s.ontologyMode==='published'?'git-branch':'shield-check','primary');}
  function context(s){const ont=s.page==='ontology';return `<div class="context-strip"><span>${icon(ont?'git-branch':'layers')}<b>${ont?s.ontologyMode==='published'?'已发布 V2 · 只读':'工作草稿 · 未发布':s.scope==='all'?'集团 · 21 家企业':company(s.scope).name}</b></span><span>${icon('clock-3')}${ont?'数据映射随版本固定':'观察日 2025-12-31'}</span><span>${icon('shield-check')}${ont?'正式使用独立核对':'已发布语义 · 精确版本固定'}</span>${tag(ont?s.ontologyMode==='published'?'语义已发布':s.validated?'校验通过':'待校验':s.page==='decision'?'事项操作样例':'现有演示数据',ont&&s.ontologyMode==='draft'?'amber':'green')}<button type="button" class="link-btn context-end" data-action="${ont?'versions':'scope'}">${ont?'查看版本状态':'范围与口径'}${icon('chevron-down')}</button></div>`;}
  function queryView(s){const result=s.queryTopic==='finance'?financeAnswer(s):riskAnswer(s);return `<section class="query-layout"><aside class="query-history"><button class="btn" data-action="new-chat">${icon('plus')}开始新的分析</button><div class="history-section"><div class="section-label">当前工作</div><button class="history-item active" data-action="topic-risk"><strong>集团债务风险跟进</strong><small>21家企业 · 固定评估结果</small></button><button class="history-item" data-action="topic-finance"><strong>重点企业融资成本</strong><small>融资余额与成本比较</small></button></div><div class="history-section"><div class="section-label">已保存视图</div><button class="history-item" data-action="saved"><strong>黄灯及以上企业</strong><small>范围、版本、证据已固定</small></button><button class="history-item" data-action="saved"><strong>环保板块资金观察</strong><small>查看保存条件</small></button></div><div class="history-bottom">${icon('shield-check')}<p>每次问答保留对象范围、数据时点和精确语义版本。</p></div></aside><div class="query-center"><div class="question-bubble"><span>${esc(s.question)}</span><span class="avatar">我</span></div><article class="panel answer"><div class="answer-body"><div class="answer-top"><span class="assistant-mark">${icon('sparkles')}</span><strong>智财问数</strong>${tag('固定结果','green','shield-check')}<span class="time">${s.queryTopic==='finance'?'融资成本分析':'债务风险 · 模型 1.0.2'}</span></div>${result}</div><footer class="answer-footer"><div>${btn('查看完整依据','evidence','shield-check','small')}${btn(s.saved?'视图已保存':'保存视图','save','bookmark','small')}${btn('导出','export','download','small')}</div>${btn('查看相关事项','to-decision','arrow-up-right','primary small')}</footer></article><div class="composer"><form id="ask-form"><label for="ask-input" class="sr-only">继续提问</label><input id="ask-input" name="question" autocomplete="off" placeholder="继续追问，例如：这些企业为什么需要关注？"><button type="submit" class="submit" aria-label="发送问题">${icon('arrow-right')}</button></form><div class="composer-foot"><button data-action="scope">${icon('layers')}沿用当前对象范围</button><span>回答引用现有数据 · 行动需人工确认</span></div></div></div><aside class="query-evidence"><section class="panel evidence-card"><h3>${icon('link')}本轮依据</h3><div class="evidence-step"><small>01 / 业务对象</small><strong>集团企业对象集</strong><p>21家金融视角企业<br>身份与范围保持一致</p></div><div class="evidence-step"><small>02 / 已发布语义</small><strong>${s.queryTopic==='finance'?'企业融资业务定义':'企业债务风险本体'}</strong><p>${s.queryTopic==='finance'?'余额加权成本 · 年利率口径':'风险语义 1.0.2 · 结果版本 1.1.0'}</p></div><div class="evidence-step"><small>03 / 固定数据</small><strong>2025-12-31</strong><p>来源与观察时点可追溯<br>历史结论不会被新版本覆盖</p></div><div class="thin-rule"></div>${link('展开证据与计算口径','evidence')}</section><section class="panel question-suggestion"><h3>继续了解</h3><button data-action="topic-reason">为什么环保公司4是红灯？${icon('arrow-up-right')}</button><button data-action="topic-finance">这些企业的融资成本如何？${icon('arrow-up-right')}</button><button data-action="to-map">在地图中查看企业关系${icon('arrow-up-right')}</button></section><p class="proof-note">${icon('circle-help')}历史风险分档与新的模型提示分别展示，结论不代表已经发生违约。</p></aside></section>`;}
  function resultTabs(s){return `<div class="segmented" aria-label="结果展示方式">${[['table','表格'],['chart','图表'],['text','文字']].map(([id,name])=>`<button type="button" data-display="${id}" class="${s.display===id?'active':''}" aria-pressed="${s.display===id}">${name}</button>`).join('')}</div>`;}
  function riskAnswer(s){const selected=s.scope==='all'?riskCompanies:riskCompanies.filter(e=>e.id===s.scope);return `<h2>${s.scope==='all'?(s.variant==='b'?`<em>${selected.length} 家企业</em>待跟进，红灯企业优先研判。`:`优先跟进 <em>${selected.length} 家</em>企业，<br>环保测试公司4需重点研判。`):`<em>${company(s.scope).name}</em>，<br>历史评估为${company(s.scope).riskTier}。`}</h2><p class="answer-intro">${s.scope==='all'?'1家红灯、4家黄灯，暂无黑灯。先核实原评估依据，再决定具体处置安排。':'本次聚焦单家企业，原观察日与历史评估版本保持一致。下方集团分布仅用于背景参照，不扩大当前对象范围。'}</p><div class="risk-stats"><div class="risk-stat"><label><i class="dot red"></i>红灯 · 重点关注</label><strong class="num">1<small>家企业</small></strong></div><div class="risk-stat"><label><i class="dot amber"></i>黄灯 · 持续跟进</label><strong class="num">4<small>家企业</small></strong></div><div class="risk-stat"><label><i class="dot"></i>绿灯 · 常态观察</label><strong class="num">16<small>家企业</small></strong></div></div><div class="result-tools"><span>需要关注的企业 · ${selected.length} 家</span>${resultTabs(s)}</div>${s.display==='table'?`<table class="data-table"><thead><tr><th>企业</th><th>历史评分</th><th>风险分档</th><th>建议下一步</th></tr></thead><tbody>${selected.map(e=>`<tr><td><button data-entity="${e.id}" data-action="portrait">${e.name}</button></td><td class="num">${fmt(e.riskScore)}</td><td>${tag(e.riskTier,e.riskTier==='红灯'?'red':'amber')}</td><td>${link(e.riskTier==='红灯'?'核对专项处置依据':'核对跟进依据','evidence','arrow-up-right',`data-entity="${e.id}"`)}</td></tr>`).join('')}</tbody></table>`:s.display==='chart'?`<div class="bar-results">${selected.map(e=>`<button class="bar-result" data-action="portrait" data-entity="${e.id}"><span>${e.name}</span><span class="bar-track"><i style="width:${e.riskScore}%"></i></span><strong>${fmt(e.riskScore)}</strong></button>`).join('')}<small class="muted">历史评分 · 0—100分，较低值需要更多关注</small></div>`:`<div class="text-results">${selected.map(e=>`<p><strong>${e.name}</strong>：历史评分 ${fmt(e.riskScore)}分，${e.riskTier}。${e.riskTier==='红灯'?'进入专项风险处置的人工研判。':'核对原模型依据并持续跟进。'}</p>`).join('')}</div>`}`;}
  function financeAnswer(s){const es=['ENT-020','ENT-007','ENT-017'].map(company).sort((a,b)=>b.metrics.cost-a.metrics.cost),total=es.reduce((t,e)=>t+e.metrics.balance,0),cost=es.reduce((t,e)=>t+e.metrics.balance*e.metrics.cost,0)/total;return `<h2>三家重点企业中，<br><em>环保测试公司4</em>融资成本最高。</h2><p class="answer-intro">以下采用金融演示快照口径，组合成本按融资本金加权。成本高低与历史风险分档分别判断。</p><div class="risk-stats"><div class="risk-stat"><label>三家合计融资余额</label><strong class="num">${fmt(total/100,1)}<small>亿元</small></strong></div><div class="risk-stat"><label>组合加权融资成本</label><strong class="num">${fmt(cost)}<small>% / 年</small></strong></div><div class="risk-stat"><label>当前分析范围</label><strong class="num">3<small>家企业</small></strong></div></div><div class="result-tools"><span>按当前融资成本排序</span>${resultTabs(s)}</div>${s.display==='table'?`<table class="data-table"><thead><tr><th>企业</th><th>融资成本</th><th>融资余额</th><th>查看</th></tr></thead><tbody>${es.map(e=>`<tr><td>${e.name}</td><td class="num">${fmt(e.metrics.cost)}%</td><td>${fmt(e.metrics.balance/100)}亿元</td><td>${link('企业画像','portrait','arrow-up-right',`data-entity="${e.id}"`)}</td></tr>`).join('')}</tbody></table>`:s.display==='chart'?`<div class="bar-results">${es.map(e=>`<div class="bar-result"><span>${e.name}</span><span class="bar-track"><i style="width:${e.metrics.cost/4*100}%"></i></span><strong>${fmt(e.metrics.cost)}%</strong></div>`).join('')}</div>`:`<div class="text-results">${es.map(e=>`<p>${e.name}当前融资成本${fmt(e.metrics.cost)}%，融资余额${fmt(e.metrics.balance/100)}亿元。</p>`).join('')}</div>`}`;}
  function getEntities(s){const list=D.enterprises.filter(e=>(!s.industry||e.industry===s.industry)&&(!s.search||[e.name,e.city].some(v=>v.includes(s.search))));return list.sort((a,b)=>s.perspective==='cost'?b.metrics.cost-a.metrics.cost:s.perspective==='maturity'?b.metrics.due-a.metrics.due:s.perspective==='exposure'?b.metrics.balance-a.metrics.balance:a.riskScore-b.riskScore);}
  function mapView(s){const selected=s.selected?company(s.selected):null,es=getEntities(s);return `<section class="map-layout"><aside class="panel entity-panel"><header class="panel-head"><div><h2>企业探索</h2><p>${es.length} 家 · 当前金融视角</p></div><button class="icon-btn" data-action="map-filters" aria-label="更多筛选">${icon('sliders-horizontal')}</button></header><label class="entity-search">${icon('search')}<input id="entity-search" placeholder="搜索企业、城市" value="${esc(s.search)}" aria-label="搜索企业"></label><div class="entity-filters"><select id="industry-filter" aria-label="产业筛选"><option value="">全部板块</option>${['环保','风电','核电'].map(x=>`<option ${s.industry===x?'selected':''}>${x}</option>`).join('')}</select><select id="perspective" aria-label="分析视角">${[['risk','历史风险'],['cost','融资成本'],['maturity','到期压力'],['exposure','银行敞口']].map(([id,n])=>`<option value="${id}" ${s.perspective===id?'selected':''}>${n}</option>`).join('')}</select></div><div class="entity-list">${es.map(e=>`<button class="entity-item ${e.id===s.selected?'active':''}" data-select="${e.id}"><strong><i class="dot ${e.riskTier==='红灯'?'red':e.riskTier==='黄灯'?'amber':''}"></i>${e.name}</strong><small>${e.city} · ${e.industry} · ${e.riskTier}</small><span>${s.perspective==='risk'?'历史评分':s.perspective==='cost'?'融资成本':s.perspective==='maturity'?'90天到期':'融资余额'}<b class="num">${s.perspective==='risk'?fmt(e.riskScore)+'分':s.perspective==='cost'?fmt(e.metrics.cost)+'%':s.perspective==='maturity'?fmt(e.metrics.due/100)+'亿元':fmt(e.metrics.balance/100)+'亿元'}</b></span></button>`).join('')||'<p class="search-empty">没有匹配企业，请调整筛选。</p>'}</div><footer>目录23家 · 金融演示范围21家</footer></aside><div class="map-canvas"><div class="map-toolbar"><div class="segmented" aria-label="地图展示形式">${[['map','地图'],['network','关系网络'],['matrix','成本 × 风险'],['list','对象明细']].map(([id,name])=>`<button data-map-view="${id}" class="${s.mapView===id?'active':''}">${name}</button>`).join('')}</div>${btn('筛选与范围','map-filters','filter','small')}</div><div class="map-badge"><span>${s.globalRelations?'全局关系':selected?'聚焦 '+selected.name:'全部企业'}</span>${selected?`<button class="link-btn" data-action="clear-map">取消选择 ×</button>`:''}</div>${s.mapView==='map'?geoMap(s,es):mapAlternate(s,es)}<div class="map-controls"><button data-action="zoom-in" aria-label="放大地图">${icon('plus')}</button><button data-action="zoom-out" aria-label="缩小地图">${icon('zoom-out')}</button><button data-action="reset-map" aria-label="全局视野">${icon('expand')}</button><button data-action="global-relations" aria-label="切换全局关系">${icon('route')}</button><button data-action="map-tools" aria-label="框选与地图工具">${icon('scan-line')}</button></div><div class="map-bottom"><div class="map-legend"><span><i class="dot red"></i>红灯</span><span><i class="dot amber"></i>黄灯</span><span><i class="dot"></i>绿灯</span><span>${icon('landmark')}银行</span></div><div class="map-credit">Natural Earth / DataV<br>城市示意位置 · 右键筛选关系</div></div></div>${selected?objectPanel(s,selected):`<aside class="panel object-panel"><div class="object-identity"><span class="object-icon">${icon('building-2')}</span></div><h2>探索企业关系</h2><p class="muted" style="margin-top:18px;font-size:14px">选择企业，查看融资、授信和担保关联；再次点击或按Esc取消选择。</p>${btn('选择环保公司4','select-default','building-2','primary')}</aside>`}</section>`;}
  function geoMap(s,es){const selected=s.selected?company(s.selected):null,edges=[],bankIds=new Set(),entityIds=new Set(es.map(e=>e.id)),focusIds=new Set(selected?[selected.id]:[]);const active=s.globalRelations?es.map(e=>e.id):selected?[selected.id]:[];
    if(s.relations.includes('financing'))D.loans.filter(l=>active.includes(l.enterpriseId)).forEach(l=>{const key=l.enterpriseId+':'+l.bankId;if(!edges.some(e=>e.key===key)){edges.push({key,from:company(l.enterpriseId),to:D.banks.find(b=>b.id===l.bankId),kind:'financing'});bankIds.add(l.bankId);}});
    if(s.relations.includes('credit'))D.facilities.filter(l=>active.includes(l.enterpriseId)).forEach(l=>{const key=l.enterpriseId+':'+l.bankId;if(!edges.some(e=>e.key===key))edges.push({key,from:company(l.enterpriseId),to:D.banks.find(b=>b.id===l.bankId),kind:'credit'});bankIds.add(l.bankId);});
    if(s.relations.includes('guarantee'))D.guarantees.filter(g=>active.includes(g.guarantorId)||active.includes(g.beneficiaryId)).forEach(g=>{edges.push({key:g.id,from:company(g.guarantorId),to:company(g.beneficiaryId),kind:'guarantee'});entityIds.add(g.guarantorId);entityIds.add(g.beneficiaryId);focusIds.add(g.guarantorId);focusIds.add(g.beneficiaryId);});
    const pathEdges=edges.filter(e=>e.to).map(e=>{const a=e.from.point,b=e.to.point,mx=(a[0]+b[0])/2,my=(a[1]+b[1])/2-Math.min(80,Math.abs(b[0]-a[0])*.35+20);return `<path class="map-edge ${e.kind}" d="M${a[0]},${a[1]} Q${mx},${my} ${b[0]},${b[1]}"><title>${e.from.name} → ${e.to.name} · ${{financing:'融资',credit:'授信',guarantee:'担保'}[e.kind]}</title></path>`;}).join('');
    const nodes=D.enterprises.filter(e=>entityIds.has(e.id)).map(e=>mapNode(e,false,s,focusIds)).join('')+D.banks.filter(b=>bankIds.has(b.id)).map(e=>mapNode(e,true,s,focusIds)).join('');
    return `<svg class="map-graphic" viewBox="0 0 1000 640" role="img" aria-label="企业及关联银行地图"><defs><radialGradient id="sea"><stop stop-color="transparent"/><stop offset="1" stop-color="transparent"/></radialGradient></defs><rect width="1000" height="640" fill="transparent" data-clear-map="true"></rect><g transform="translate(${500-500*s.zoom},${320-320*s.zoom}) scale(${s.zoom})"><g class="map-grid">${[140,300,460,620,780,940].map(x=>`<path d="M${x},0 V640"></path>`).join('')}${[90,230,370,510].map(y=>`<path d="M0,${y} H1000"></path>`).join('')}</g><g data-clear-map="true">${D.provinces.map(p=>`<path class="province" d="${p.path}"><title>${p.name}</title></path>`).join('')}</g><text class="geo-label" x="330" y="330">中国</text><text class="geo-label" x="390" y="115">蒙古</text><text class="geo-water" x="853" y="365">东海</text><text class="geo-water" x="685" y="590">南海</text><g>${pathEdges}</g><g>${nodes}</g></g></svg>`;
  }
  function mapNode(e,bank,s,focusIds){const selected=e.id===s.selected,focus=selected||bank||focusIds.has(e.id),[x,y]=e.point,label=focus||['ENT-001','ENT-007','ENT-017','ENT-020','ENT-021'].includes(e.id),tone=e.riskTier==='红灯'?'var(--red)':e.riskTier==='黄灯'?'var(--amber)':'var(--green)';return `<g class="map-node ${selected?'selected':''} ${s.selected&&!focus&&!s.globalRelations?'faded':''}" transform="translate(${x},${y})" ${bank?`data-bank="${e.id}"`:`data-select="${e.id}"`} tabindex="0" role="button" aria-label="${e.name}"><circle r="${selected?22:bank?17:13}" fill="${selected?'var(--accent-soft)':'transparent'}"></circle><circle class="node-fill" r="${selected?16:bank?13:10}" ${bank||selected?'':`style="stroke:${tone}"`}></circle><svg x="${selected?-11:bank?-8:-6}" y="${selected?-11:bank?-8:-6}" width="${selected?22:bank?16:12}" height="${selected?22:bank?16:12}" class="ico" viewBox="0 0 24 24">${D.icons[bank?'landmark':'building-2']}</svg>${label?`<text class="node-label" text-anchor="${e.id==='ENT-020'?'start':'middle'}" x="${e.id==='ENT-020'?24:0}" y="${e.id==='ENT-020'?5:-22}">${e.name.replace('测试','')}</text>`:''}<title>${e.name}${bank?' · 融资机构':' · '+e.city+' · '+e.riskTier}</title></g>`;}
  function objectPanel(s,e){return `<aside class="panel object-panel"><div class="object-identity"><span class="object-icon">${icon('building-2')}</span>${tag(e.riskTier,e.riskTier==='红灯'?'red':e.riskTier==='黄灯'?'amber':'green')}</div><h2>${e.name}</h2><div class="object-subtitle"><span>${e.city} / ${e.industry}</span><span>·</span><span>${e.id}</span></div><div class="object-metrics"><div><label>融资成本</label><strong class="num">${fmt(e.metrics.cost)}<small>%</small></strong></div><div><label>历史风险评分</label><strong class="num">${fmt(e.riskScore)}<small>分</small></strong></div><div><label>融资余额</label><strong class="num">${money(e.metrics.balance)}</strong></div><div><label>90天到期本金</label><strong class="num">${money(e.metrics.due)}</strong></div></div><section class="relations-control"><h3>选择要呈现的关系</h3><div class="relation-toggles">${[['financing','融资'],['credit','授信'],['guarantee','担保']].map(([k,n])=>`<label><input type="checkbox" data-relation="${k}" ${s.relations.includes(k)?'checked':''}>${n}</label>`).join('')}</div></section><div class="object-signal"><strong>${icon('shield-alert')}关注什么</strong><p>${e.riskTier==='红灯'?'历史评估为红灯，需核实偿债能力与原模型依据。':'结合成本、到期与资金覆盖，核对当前关注事项。'}地图关系不代表风险已发生传染。</p></div><div class="object-actions">${btn('打开企业全景','portrait','arrow-up-right','primary',`data-entity="${e.id}"`)}<div>${btn('围绕企业提问','object-query','message-square','',`data-entity="${e.id}"`)}${btn('使用模型','models','workflow')}</div>${link('核对关联来源','evidence')}</div></aside>`;}
  function mapAlternate(s,es){if(s.mapView==='list')return `<div class="map-alt"><table class="data-table"><thead><tr><th>企业</th><th>融资成本</th><th>历史风险</th></tr></thead><tbody>${es.map(e=>`<tr><td><button data-select="${e.id}">${e.name}</button></td><td>${fmt(e.metrics.cost)}%</td><td>${tag(e.riskTier,e.riskTier==='红灯'?'red':e.riskTier==='黄灯'?'amber':'green')}</td></tr>`).join('')}</tbody></table></div>`;if(s.mapView==='matrix')return `<div class="map-alt"><svg viewBox="0 0 750 470" aria-label="融资成本与历史风险矩阵"><path d="M65 25 V400 H715" stroke="var(--line)" fill="none"></path>${[0,20,40,60,80,100].map(v=>`<text x="50" y="${405-v*3.6}" text-anchor="end" fill="var(--muted)" font-size="13">${v}</text>`).join('')}${[0,1,2,3,4].map(v=>`<text x="${65+v*155}" y="425" fill="var(--muted)" font-size="13">${v}%</text>`).join('')}${es.map(e=>`<circle class="matrix-point" cx="${65+e.metrics.cost*155}" cy="${400-e.riskScore*3.6}" r="8" data-select="${e.id}" tabindex="0"><title>${e.name} · ${fmt(e.metrics.cost)}% · ${fmt(e.riskScore)}分</title></circle>`).join('')}<text x="355" y="460" fill="var(--muted)" font-size="13">融资成本（年利率）</text></svg></div>`;const e=company(s.selected||'ENT-020'),banks=D.banks.filter(b=>D.loans.some(l=>l.enterpriseId===e.id&&l.bankId===b.id));return `<div class="map-alt"><svg viewBox="0 0 750 470" aria-label="企业融资关系网络">${banks.map((b,i)=>{const x=160+i*205,y=110+Math.abs(i-1)*230;return `<path d="M375 235 L${x} ${y}" fill="none" stroke="var(--accent)" stroke-width="2"></path><g data-bank="${b.id}" role="button" tabindex="0" transform="translate(${x},${y})"><circle r="31" fill="var(--surface)" stroke="var(--accent)"></circle><text y="55" text-anchor="middle" fill="var(--ink)" font-size="14">${b.name}</text><svg x="-12" y="-12" width="24" height="24" class="ico" viewBox="0 0 24 24">${D.icons.landmark}</svg></g>`;}).join('')}<g transform="translate(375 235)"><circle r="43" fill="var(--accent-soft)" stroke="var(--accent)" stroke-width="2"></circle><svg x="-15" y="-15" width="30" height="30" class="ico" viewBox="0 0 24 24">${D.icons['building-2']}</svg><text y="69" text-anchor="middle" fill="var(--ink)" font-size="16">${e.name}</text></g></svg></div>`;}
  const cases=[{id:'case-20',entity:'ENT-020',title:'专项风险处置',source:'模型提示',score:23.05,tone:'red'},{id:'case-17',entity:'ENT-017',title:'债务风险分档跟踪',source:'报告 / 驾驶舱',score:30.52,tone:'amber'},{id:'case-18',entity:'ENT-018',title:'债务风险分档跟踪',source:'报告 / 驾驶舱',score:33.92,tone:'amber'},{id:'case-07',entity:'ENT-007',title:'融资置换询价',source:'AI 推荐方案',score:37.75,tone:'amber'},{id:'case-19',entity:'ENT-019',title:'债务风险分档跟踪',source:'模型提示',score:37.31,tone:'amber'}];
  function decisionView(s){const chosen=cases.find(c=>c.id===s.caseId)||cases[0],e=company(chosen.entity),stage=s.caseStages[chosen.id]??1,filtered=cases.filter(c=>s.caseFilter==='all'||(s.caseFilter==='approval'?(s.caseStages[c.id]??1)===1:(s.caseStages[c.id]??1)>=2));return `<section class="decision-layout"><aside class="panel case-list"><header class="panel-head"><div><h2>待处理事项</h2><p>按事项阶段继续工作</p></div>${tag('样例 '+cases.length)}</header><nav class="case-tabs" aria-label="事项阶段筛选">${[['all','全部'],['approval','待批准'],['execution','执行与复核']].map(([id,name])=>`<button data-case-filter="${id}" class="${s.caseFilter===id?'active':''}">${name}</button>`).join('')}<button data-action="case-filters" aria-label="来源与负责人筛选">${icon('filter')}</button></nav><div class="case-scroll">${filtered.map(c=>`<button class="case-row ${c.id===chosen.id?'active':''}" data-case="${c.id}"><div><strong>${company(c.entity).name}</strong>${tag(phases[s.caseStages[c.id]??1],s.caseStages[c.id]>=2?'green':'amber')}</div><h3>${c.title}</h3><div><small>${c.source}</small><small>依据日 12.31</small></div></button>`).join('')||'<p class="search-empty">当前阶段没有样例事项。</p>'}</div><div class="panel-head">${link('查看全部来源与原办理','original-records')}</div></aside><article class="panel case-detail"><header class="case-title"><div><div class="eyebrow">CASE / ${chosen.entity}</div><h2>${e.name} · ${chosen.title}</h2><p>${chosen.source}　·　固定依据日 2025-12-31　·　事项状态为演示样例</p></div>${tag(phases[stage],stage>=2?'green':'amber')}</header><ol class="process-track" aria-label="事项处理阶段" style="list-style:none;padding-left:0">${phases.map((p,i)=>`<li class="process-step ${i<stage?'done':i===stage?'active':''}"><b>${i<stage?'✓':i+1}</b><span>${p}</span></li>`).join('')}</ol><div class="case-detail-grid"><section><div class="basis-head"><strong>先看依据，再作决定</strong>${link('完整回溯','trace')}</div><div class="basis-card">${tag(chosen.source,chosen.tone)}<strong>${chosen.id==='case-07'?'原借据融资置换空间':'历史债务风险评估结果'}</strong><div class="basis-value"><strong class="num">${chosen.id==='case-07'?'37.72':fmt(chosen.score)}</strong><span>${chosen.id==='case-07'?'bp · 参考降息空间':'分 · 最终历史评分'}</span>${tag(chosen.id==='case-07'?'板块均值兜底':e.riskTier,chosen.tone)}</div><p>${chosen.id==='case-07'?'原借据 DEMO-DEBT-003803，参考利率2.17%。费用、有效报价和可置换条件尚需核实。':'评分引用原模型1.0.2与固定结果版本。风险分档用于提示关注，不等同于企业已经发生违约。'}</p>${link('查看来源记录','evidence')}</div><div class="case-recommendation"><h3>建议关注的下一步</h3><p>${chosen.id==='case-07'?'取得银行报价，核实授信额度、提前还款条件与置换费用，再复核净节省额。':'核实未来偿债安排、可用资金与原评估依据，明确跟进责任和处理期限。处置意见经人工审阅后进入办理。'}</p></div><div class="source-track"><button data-action="evidence">数据与本体</button>${icon('arrow-right')}<button data-action="models">${chosen.id==='case-07'?'AI置换运行':'模型评估'}</button>${icon('arrow-right')}<button data-action="trace">行动事项</button></div></section><aside class="handling-panel"><h3>${stage===1?'审阅并决定':stage===2?'确认承接':stage===3?'登记执行进展':stage===4?'复核业务效果':stage===5?'已完成效果复核':'研判并提交'}</h3><dl class="handling-info"><div><dt>处理负责人</dt><dd class="person"><span class="avatar">财</span>${e.industry}业务负责人</dd></div><div><dt>办理期限</dt><dd>2026-09-25</dd></div></dl><label for="handling-note">${stage===4?'效果复核意见':'办理意见'}<textarea id="handling-note" placeholder="${stage===4?'填写后续效果依据和复核结论':'说明本次决定及需要落实的工作'}">${esc(s.note)}</textarea></label>${btn(({'-1':'记录原因后重开',0:'提交待批准',1:'批准并分办',2:'确认承接',3:'登记执行凭证',4:'登记效果复核',5:'查看结项依据'})[stage],stage===-1?'reopen-case':'advance-case',stage===1?'check':stage===4?'file-check-2':'arrow-right','primary')}<div class="handling-secondary">${btn(stage===1?'退回补充':'其他处理','other-case','','small')}${btn(stage===1?'拒绝并说明':'生成报告',stage===1?'reject-case':'report','','small')}</div><p class="handling-foot">${stage<=1?'批准仅代表同意安排，后续仍需承接与执行。':stage<=3?'执行凭证完整后才可确认执行完成，随后独立复核效果。':'效果达成必须有后续证据，不由办理状态自动推断。'}</p></aside></div><footer class="case-audit">${icon('clock-3')}<span>${s.caseEvents.length?s.caseEvents.at(-1):'来源结果 → 形成事项 → 等待人工决定'}</span>${link('办理记录','trace')}</footer></article></section>`;}
  const ontologyNodes=[{id:'enterprise',name:'企业',type:'OBJECT TYPE',icon:'building-2',x:340,y:203,w:186,props:['企业编号','企业名称','所属产业','历史风险评分']},{id:'loan',name:'融资记录',type:'OBJECT TYPE',icon:'file-text',x:72,y:70,w:174,props:['原借据编号','融资主体','借据余额','当前利率']},{id:'bank',name:'融资机构',type:'OBJECT TYPE',icon:'landmark',x:340,y:25,w:180,props:['机构编号','机构名称','机构类别']},{id:'department',name:'预算部门',type:'OBJECT TYPE',icon:'database',x:626,y:83,w:174,props:['部门编号','部门名称','所属企业']},{id:'holding',name:'产品汇总持仓',type:'OBJECT TYPE',icon:'layers',x:68,y:358,w:188,props:['持仓编号','台账范围','产品编号','观察日期']},{id:'risk',name:'风险关注规则',type:'RULE',icon:'shield-alert',x:345,y:401,w:187,props:['规则编号','阈值口径','所属版本','触发条件']},{id:'action',name:'受控行动',type:'ACTION TYPE',icon:'git-pull-request-arrow',x:625,y:335,w:174,props:['行动类型','输入对象','前置条件','人工确认']}];
  function ontologyView(s){const node=ontologyNodes.find(n=>n.id===s.node)||ontologyNodes[0];return `<section class="ontology-layout"><aside class="resource-panel"><h2>语义资源</h2><div class="resource-group"><div class="resource-heading"><span>对象类型</span><span>11</span></div>${ontologyNodes.filter(n=>n.type==='OBJECT TYPE').map(n=>`<button class="resource-item ${n.id===s.node?'active':''}" data-node="${n.id}">${icon(n.icon)}${n.name}</button>`).join('')}<button class="resource-item" data-action="resources">${icon('ellipsis')}查看全部对象<span class="resource-count">11</span></button></div><div class="resource-group"><div class="resource-heading"><span>业务逻辑</span></div><button class="resource-item" data-action="relations">${icon('link')}关系<span class="resource-count">10</span></button><button class="resource-item" data-action="metrics">${icon('chart-no-axes-combined')}指标<span class="resource-count">8</span></button><button class="resource-item ${s.node==='risk'?'active':''}" data-node="risk">${icon('shield-alert')}规则<span class="resource-count">3</span></button><button class="resource-item ${s.node==='action'?'active':''}" data-node="action">${icon('git-pull-request-arrow')}行动<span class="resource-count">1</span></button></div>${btn('添加语义资源','add-resource','plus','small')}<div class="resource-foot">工作草稿与已发布版本独立。<br>修改后需重新校验。</div></aside><div class="graph-panel"><header class="graph-toolbar"><div class="segmented"><button class="${s.graphMode==='semantic'?'active':''}" data-graph-mode="semantic">业务语义</button><button class="${s.graphMode==='lineage'?'active':''}" data-graph-mode="lineage">数据血缘</button></div><div><button class="icon-btn" data-action="graph-fit" aria-label="适配画布">${icon('expand')}</button><button class="icon-btn" data-action="graph-filter" aria-label="显示依赖范围">${icon('sliders-horizontal')}</button></div></header><div class="graph-canvas">${s.graphMode==='semantic'?ontologyGraph(s):lineageGraph()}</div><div class="graph-legend"><span><i></i>对象类型</span><span><i></i>规则与指标</span><span><i></i>受控行动</span><span>主干视图 · 7个资源</span></div><footer class="graph-status">${icon(s.ontologyMode==='published'?'shield-check':s.validated?'circle-check':'circle-help')}<span>${s.ontologyMode==='published'?'已发布 V2 · 数据映射已冻结':s.validated?'当前工作草稿校验通过，可发布新版本':'工作草稿已修改，请重新校验'}</span>${link(s.ontologyMode==='published'?'查看发布记录':'查看校验详情',s.ontologyMode==='published'?'versions':'validation')}</footer></div><aside class="property-panel">${tag(node.type==='RULE'?'业务规则':node.type==='ACTION TYPE'?'受控行动':'对象类型')}<h2>${node.name}</h2><p class="mono">${({enterprise:'OBJ-ENTERPRISE',loan:'OBJ-FINANCING-LOAN',bank:'OBJ-FINANCIAL-INSTITUTION',department:'OBJ-BUDGET-DEPARTMENT',holding:'OBJ-INVESTMENT-HOLDING',risk:'RISK-RULE',action:'ACTION-TYPE'})[node.id]}</p><nav class="property-tabs"><button class="${s.propertyTab==='fields'?'active':''}" data-property-tab="fields">属性</button><button class="${s.propertyTab==='binding'?'active':''}" data-property-tab="binding">数据绑定</button><button class="${s.propertyTab==='usage'?'active':''}" data-property-tab="usage">消费</button></nav>${s.propertyTab==='fields'?`<h3>核心属性</h3>${node.props.map((p,i)=>`<div class="property-row"><span>${p}</span><small>${i===0?'主键 · 文本':p.includes('分')||p.includes('余额')||p.includes('利率')?'数值':'文本'}</small></div>`).join('')}<div class="property-binding"><span>绑定的已发布数据资产</span><strong>${node.id==='loan'?'融资借据明细':node.id==='holding'?'投资持仓台账':'企业业务全景资产'}</strong><small>字段映射随本体版本固定</small>${link('核对字段映射','binding')}</div>`:s.propertyTab==='binding'?`<h3>数据资产与映射</h3><p class="muted" style="font-size:12px;line-height:1.9">主键、字段类型、来源与映射版本全部保留。发布后调整需通过新草稿。</p><div class="property-binding"><strong>已发布资产</strong><p>固定映射 · 原始来源可追溯</p>${link('展开映射明细','binding')}</div>`:`<h3>下游消费</h3>${['对象全景','问数工作台','模型与算法','决策中心'].map(x=>`<div class="property-row"><span>${x}</span>${tag('可追溯','green')}</div>`).join('')}<div class="thin-rule"></div>${link('查看消费证据','consumption')}`}<button class="btn" data-action="${s.ontologyMode==='published'?'revise':'edit-property'}">${icon(s.ontologyMode==='published'?'git-branch':'settings-2')}${s.ontologyMode==='published'?'在工作草稿中修订':'编辑当前资源'}</button></aside></section>`;}
  function ontologyGraph(s){return `<svg class="ontology-svg" viewBox="0 0 870 500" role="img" aria-label="企业业务本体语义关系"><g><path class="onto-edge" d="M246 110 C300 110 285 243 340 243"></path><path class="onto-edge" d="M432 105 V203"></path><path class="onto-edge" d="M526 243 C580 243 571 123 626 123"></path><path class="onto-edge" d="M256 398 C304 398 284 265 340 265"></path><path class="onto-edge dashed" d="M433 283 V401"></path><path class="onto-edge" d="M526 263 C580 263 575 375 625 375"></path><path class="onto-edge dashed" d="M532 441 C579 441 570 395 625 395"></path><text class="onto-edge-label" x="271" y="165">借款主体</text><text class="onto-edge-label" x="444" y="159">关联融资</text><text class="onto-edge-label" x="565" y="174">所属部门</text><text class="onto-edge-label" x="256" y="341">业务关联</text><text class="onto-edge-label" x="445" y="348">评估与监控</text><text class="onto-edge-label" x="563" y="312">行动对象</text><text class="onto-edge-label" x="550" y="459">触发候选</text></g>${ontologyNodes.map(n=>`<g class="onto-node ${n.id===s.node?'active':''}" data-node="${n.id}" tabindex="0" role="button" aria-label="${n.name}" transform="translate(${n.x},${n.y})"><rect width="${n.w}" height="80"></rect><svg x="15" y="18" width="23" height="23" class="ico" viewBox="0 0 24 24">${D.icons[n.icon]}</svg><text class="node-label" x="49" y="33">${n.name}</text><text class="node-type" x="49" y="54">${n.type}</text><circle cx="0" cy="40" r="3" fill="var(--surface)" stroke="var(--line)"></circle><circle cx="${n.w}" cy="40" r="3" fill="var(--surface)" stroke="var(--line)"></circle></g>`).join('')}</svg>`;}
  function lineageGraph(){return `<svg class="ontology-svg" viewBox="0 0 870 500" role="img" aria-label="数据资产到语义及应用的血缘"><path d="M250 220 H338 M530 220 H610" stroke="var(--accent)" fill="none" stroke-width="2"></path>${[{x:65,label:'已发布数据资产',small:'数据工程 · 固定快照',i:'database'},{x:338,label:'本体字段映射',small:'语义版本 · 精确绑定',i:'network'},{x:610,label:'业务应用',small:'对象 / 问数 / 决策',i:'workflow'}].map(n=>`<g class="onto-node" data-action="binding" tabindex="0" role="button" transform="translate(${n.x},170)"><rect width="192" height="105"></rect><svg class="ico" x="20" y="18" width="24" height="24" viewBox="0 0 24 24">${D.icons[n.i]}</svg><text class="node-label" x="20" y="66">${n.label}</text><text class="node-type" x="20" y="87">${n.small}</text></g>`).join('')}<text class="onto-edge-label" x="190" y="350">原始来源、转换、字段映射与消费记录分别留存</text></svg>`;}
  return {D,esc,icon,btn,link,tag,fmt,company,riskCompanies,pages,themes,phases,cases,ontologyNodes,reviewBar,shell,getEntities,geoMap};
})();
